#

import time
from brian.motors import EV3LargeMotor
from brian.motors import MotorPort
from brian.sensors.EV3 import GyroSensorEV3
from brian.sensors import SensorPort
from brian.motors import EV3MediumMotor
from brian.sensors.EV3 import UltrasonicSensorEV3
from brian.sensors.EV3 import TouchSensorEV3
import math

HowFar_ = None
HowFarUntilFrontRow = None
rychlost = None
HowFarUntilBackRow = None
left = None
pas = None
Start_stop = None
right = None
Breaking_speed = None
AccelerationCompleted_ = None
gyro = None
TouchZavora = None
US = None

def sensor_retry(sensor, call_fun):
  from brian.sensors import SensorIsNotReadyError
  while True:
    try:
      sensor.wait_until_ready()
      return call_fun()
    except SensorIsNotReadyError:
      # Čtení senzoru může selhat. Opakuj při chybě
      pass

# Popište tuto funkci...
def Beninging_config():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  HowFarUntilFrontRow = 260
  HowFarUntilBackRow = 465
  Breaking_speed = 200
  AccelerationCompleted_ = 0
  sensor_retry(gyro, gyro.set_zero_point)
  time.sleep(0.3)

# Popište tuto funkci...
def START():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  left = EV3LargeMotor(MotorPort.D)
  right = EV3LargeMotor(MotorPort.C)
  gyro = GyroSensorEV3(SensorPort.S1)
  pas = EV3MediumMotor(MotorPort.A)
  US = UltrasonicSensorEV3(SensorPort.S2)
  TouchZavora = TouchSensorEV3(SensorPort.S3)
  Start_stop = TouchSensorEV3(SensorPort.S4)

# Popište tuto funkci...
def First_Side():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  for count in range(3):
    Gate_collect_block()
    Collect_Bloct_To_Front_Row()
  Gate_close()
  Breaking_speed = Breaking_speed + 10

def motor_retry(motor, call_fun):
  from brian.motors import MotorIsNotReadyError
  while True:
    try:
      motor.wait_until_ready()
      return call_fun()
    except MotorIsNotReadyError:
      # Ovládání motoru může selhat. Opakuj při chybě
      pass

# Popište tuto funkci...
def Gate_reset():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  Start_stop.wait_for_press()
  motor_retry(pas, pas.brake)

# Popište tuto funkci...
def First_Reset():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  DriveBackward(-390)
  Turn_left()
  sensor_retry(gyro, gyro.set_zero_point)
  time.sleep(0.5)
  Wall_back_ram()
  Gate_open()

# Skopčenej kod z minulého roku, je to nastavené
# na současné proporce, snad by to mělo fungovat
def Drive_Forward_Until_Block_Detected():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  motor_retry(left, lambda: left.reset_angle(0))
  motor_retry(right, lambda: right.reset_angle(0))
  print('Hledám blok')
  rychlost = 0
  while not sensor_retry(US, US.distance_mm) <= 300:
    if 240 >= rychlost:
      if 40 >= rychlost:
        rychlost = rychlost + 0.05
      else:
        rychlost = rychlost + 4
    motor_retry(left, lambda: left.run_at_speed((rychlost - 8 * sensor_retry(gyro, gyro.angle)) + Breaking_speed))
    motor_retry(right, lambda: right.run_at_speed((rychlost + 8 * sensor_retry(gyro, gyro.angle)) + Breaking_speed))
  print('Vidím blok')
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Skopčenej kod z minulého roku, je to nastavené
# na současné proporce, snad by to mělo fungovat
def DriveBackward(HowFar_):
  global HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  motor_retry(left, lambda: left.reset_angle(0))
  while motor_retry(left, left.current_angle) >= HowFar_:
    print(sensor_retry(gyro, gyro.angle))
    motor_retry(left, lambda: left.run_at_speed(-360 - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(-360 + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Popište tuto funkci...
def Second_Side():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  Collect_Bloct_To_Front_Row()
  Gate_collect_block()
  for count2 in range(2):
    Collect_Bloct_To_Front_Row()
    Gate_collect_block()
  Collect_Bloct_To_Front_Row()
  Gate_close()
  Breaking_speed = Breaking_speed + 10

# Popište tuto funkci...
def Collect_Bloct_To_Back_Row():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  Drive_Forward_Until_Block_Detected()
  print('Najíždím na blok')
  motor_retry(left, lambda: left.reset_angle(0))
  motor_retry(right, lambda: right.reset_angle(0))
  while motor_retry(left, left.current_angle) <= HowFarUntilBackRow or motor_retry(right, right.current_angle) <= HowFarUntilBackRow:
    rychlost = (1 - math.exp(-0.03 * (HowFarUntilBackRow - motor_retry(left, left.current_angle)))) * 220 + Breaking_speed
    motor_retry(left, lambda: left.run_at_speed(rychlost - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(rychlost + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Popište tuto funkci...
def Second_Reset():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  DriveBackward(-600)
  Turn_left()
  sensor_retry(gyro, gyro.set_zero_point)
  time.sleep(0.5)
  Wall_back_ram()
