def Collect_Bloct_To_Front_Row():
  global HowFar_, HowFarUntilFrontRow, rychlost, HowFarUntilBackRow, left, pas, Start_stop, right, Breaking_speed, AccelerationCompleted_, gyro, TouchZavora, US
  Drive_Forward_Until_Block_Detected()
  print('Najíždím na blok')
  motor_retry(left, lambda: left.reset_angle(0))
  motor_retry(right, lambda: right.reset_angle(0))
  while motor_retry(left, left.current_angle) <= HowFarUntilFrontRow or motor_retry(right, right.current_angle) <= HowFarUntilFrontRow:
    rychlost = ((HowFarUntilFrontRow - motor_retry(left, left.current_angle)) / HowFarUntilFrontRow) * 220 + Breaking_speed
    motor_retry(left, lambda: left.run_at_speed(rychlost - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(rychlost + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

